package com.bank.liquibase.model;

// One atomic, immutable-once-applied schema change with a checksum.
public class ChangeSet {
    private final String id;
    private final String author;
    private final String filename;
    private String forwardSql;      // the change to apply
    private final String rollbackSql;

    public ChangeSet(String id, String author, String filename,
                     String forwardSql, String rollbackSql) {
        this.id = id;
        this.author = author;
        this.filename = filename;
        this.forwardSql = forwardSql;
        this.rollbackSql = rollbackSql;
    }

    // Unique identity = id + author + filename.
    public String identity() { return id + "::" + author + "::" + filename; }

    // Checksum detects tampering with an already-applied changeSet.
    public int checksum() { return forwardSql.hashCode(); }

    // Used only to SIMULATE illegal editing after the fact.
    public void tamper(String newSql) { this.forwardSql = newSql; }

    public String getForwardSql() { return forwardSql; }
    public String getRollbackSql() { return rollbackSql; }
}
