package com.bank.liquibase.tracking;

import java.util.HashMap;
import java.util.Map;

// Models DATABASECHANGELOG: remembers which changeSets were applied + checksum.
public class DatabaseChangeLogTable {
    // identity -> stored checksum
    private final Map<String, Integer> applied = new HashMap<>();

    public boolean isApplied(String identity) { return applied.containsKey(identity); }
    public Integer storedChecksum(String identity) { return applied.get(identity); }
    public void record(String identity, int checksum) { applied.put(identity, checksum); }
}
