package com.bank.liquibase.tracking;

import java.util.concurrent.atomic.AtomicBoolean;

// Models DATABASECHANGELOGLOCK: only one instance migrates at a time.
public class ChangeLogLock {
    private final AtomicBoolean locked = new AtomicBoolean(false);

    public boolean acquire() { return locked.compareAndSet(false, true); }
    public void release() { locked.set(false); }
}
