package com.bank.liquibase.engine;

import com.bank.liquibase.changelog.ChangeLog;
import com.bank.liquibase.model.ChangeSet;
import com.bank.liquibase.tracking.ChangeLogLock;
import com.bank.liquibase.tracking.DatabaseChangeLogTable;
import java.util.logging.Level;
import java.util.logging.Logger;

// Applies ONLY unapplied changeSets; verifies checksums; holds the lock.
public class LiquibaseRunner {
    private static final Logger log = Logger.getLogger(LiquibaseRunner.class.getName());
    private final DatabaseChangeLogTable tracking;
    private final ChangeLogLock lock;

    public LiquibaseRunner(DatabaseChangeLogTable tracking, ChangeLogLock lock) {
        this.tracking = tracking;
        this.lock = lock;
    }

    public void update(ChangeLog changeLog) {
        if (!lock.acquire()) {
            log.warning("another instance holds the changelog lock — waiting");
            return;
        }
        try {
            for (ChangeSet cs : changeLog.getChangeSets()) {
                String id = cs.identity();
                if (tracking.isApplied(id)) {
                    // Verify the applied changeSet was not edited later.
                    if (tracking.storedChecksum(id) != cs.checksum()) {
                        throw new IllegalStateException(
                            "checksum mismatch for " + id + " — changeSet was altered!");
                    }
                    log.fine(() -> "skip (already applied): " + id);
                    continue;
                }
                // Apply the forward SQL and record it.
                log.info(() -> "applying: " + id + " -> " + cs.getForwardSql());
                tracking.record(id, cs.checksum());
            }
        } finally {
            lock.release();
        }
    }
}
