package com.bank.liquibase;

import com.bank.liquibase.changelog.ChangeLog;
import com.bank.liquibase.engine.LiquibaseRunner;
import com.bank.liquibase.model.ChangeSet;
import com.bank.liquibase.tracking.ChangeLogLock;
import com.bank.liquibase.tracking.DatabaseChangeLogTable;
import java.util.logging.Level;
import java.util.logging.Logger;

public class LiquibaseDemo {
    private static final Logger log = Logger.getLogger(LiquibaseDemo.class.getName());

    public static void main(String[] args) {
        DatabaseChangeLogTable tracking = new DatabaseChangeLogTable();
        ChangeLogLock lock = new ChangeLogLock();
        LiquibaseRunner runner = new LiquibaseRunner(tracking, lock);

        ChangeSet cs1 = new ChangeSet("1-create-accounts", "rajesh", "master.yaml",
            "CREATE TABLE accounts (id VARCHAR(20) PRIMARY KEY, balance DECIMAL(15,2))",
            "DROP TABLE accounts");

        // First run: only cs1 exists.
        ChangeLog changeLog = new ChangeLog().add(cs1);
        log.info("=== first run (fresh database) ===");
        runner.update(changeLog);

        // Add a second changeSet and run again: only cs2 applies.
        ChangeSet cs2 = new ChangeSet("2-add-upi-handle", "priya", "master.yaml",
            "ALTER TABLE accounts ADD COLUMN upi_handle VARCHAR(50)", null);
        changeLog.add(cs2);
        log.info("=== second run (cs1 already applied) ===");
        runner.update(changeLog);

        // Illegally edit cs1 after it was applied → checksum mismatch.
        log.info("=== tampering with an applied changeSet ===");
        cs1.tamper("CREATE TABLE accounts (id VARCHAR(20))");
        try {
            runner.update(changeLog);
        } catch (IllegalStateException e) {
            log.log(Level.SEVERE, "Liquibase refused to run: " + e.getMessage(), e);
        }
    }
}
